            1 -> listOf(
                QuranAyah(1, 1, 1, "الفَاتِحَة", "Al-Fatihah", 1, "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "اللہ کے نام سے شروع جو بہت مہربان رحمت والا"),
